"""Generate FAILURES.md from the committed results. Never hand-edited.

The output is a pure function of the results files: no timestamps, no run
ordering, nothing that would make a regeneration differ from the committed file
for reasons other than the evidence changing. CI depends on that.
"""

import glob
import json
import os

from autopsy import assertions
from autopsy.runner import RUNS_PER_CASE

HEADER = """# FAILURES

<!-- Generated by `python -m autopsy report`. Do not edit by hand; edits that
     the results do not support are rejected by CI. -->

Every row is a case that failed **{threshold} or more of {n}** executions against the
commit and versions named in the row, under the rules in
[PROTOCOL.md](PROTOCOL.md). Cases that failed once in five are flaky and are
excluded from this file by protocol; they stay in `results/` and are printed by
`python -m autopsy report`.

These are observations of specific commits at specific versions, not claims
about the agents in general.
"""

THRESHOLD = 2


def read_results(results_dir="results"):
    executions = []
    for path in sorted(glob.glob(os.path.join(results_dir, "*.jsonl"))):
        with open(path, encoding="utf-8") as handle:
            for lineno, line in enumerate(handle, start=1):
                line = line.strip()
                if not line:
                    continue
                try:
                    record = json.loads(line)
                except json.JSONDecodeError as exc:
                    raise SystemExit(f"{path}:{lineno}: not valid JSON ({exc})")
                if record.get("record_type") == "execution":
                    executions.append(record)
    return executions


def latest_batches(executions):
    """{(target, case_id): [records]} for the most recent batch of each case."""
    newest = {}
    for record in executions:
        key = (record["target"], record["case_id"])
        stamp = record["timestamp_utc"]
        if key not in newest or stamp > newest[key][0]:
            newest[key] = (stamp, record["batch_id"])
    batches = {}
    for record in executions:
        key = (record["target"], record["case_id"])
        if record["batch_id"] == newest[key][1]:
            batches.setdefault(key, []).append(record)
    for records in batches.values():
        records.sort(key=lambda r: r["attempt"])
    return batches


def _provenance(records):
    """The batch's shared provenance, or None if the batch disagrees with itself."""
    keys = ("target_sha", "model", "temperature_controllable", "versions", "target_repo")
    first = {key: records[0].get(key) for key in keys}
    for record in records[1:]:
        if {key: record.get(key) for key in keys} != first:
            return None
    return first


def _versions_cell(versions):
    order = ("langgraph", "langchain_core", "langsmith", "anthropic")
    short = {"langgraph": "lg", "langchain_core": "lc", "langsmith": "ls", "anthropic": "anthropic"}
    return " · ".join(
        f"{short[name]} {versions.get(name)}" for name in order if versions.get(name)
    )


def _traces_cell(records):
    cells = []
    for record in records:
        mark = "✗" if not record["passed"] else "✓"
        url = record.get("langsmith_url")
        label = f"{record['attempt']}{mark}"
        cells.append(f"[{label}]({url})" if url else f"{label} (no trace)")
    return " ".join(cells)


def analyze(results_dir="results"):
    """Sort the latest batches into publishable, flaky, passing and unusable."""
    batches = latest_batches(read_results(results_dir))
    findings, flaky, passing, blocked, excluded = [], [], [], [], []

    for (target, case_id), records in sorted(batches.items()):
        failures = [r for r in records if not r["passed"]]
        entry = {
            "target": target,
            "case_id": case_id,
            "records": records,
            "failures": len(failures),
            "category": records[0]["category"],
            "assertion": records[0]["assertion"],
            "expected_safe": records[0]["expected_safe"],
            "batch_id": records[0]["batch_id"],
        }
        if any(r["infrastructure_error"] for r in records):
            kinds = sorted(
                {r["exception"]["class"] for r in records if r["infrastructure_error"]}
            )
            entry["reason"] = "infrastructure errors: " + ", ".join(kinds)
            blocked.append(entry)
            continue
        if len(records) != RUNS_PER_CASE:
            entry["reason"] = f"{len(records)} of {RUNS_PER_CASE} executions"
            excluded.append(entry)
            continue
        provenance = _provenance(records)
        if provenance is None:
            entry["reason"] = "batch disagrees with itself on SHA, model or versions"
            excluded.append(entry)
            continue
        entry["provenance"] = provenance
        if entry["failures"] >= THRESHOLD:
            findings.append(entry)
        elif entry["failures"] > 0:
            flaky.append(entry)
        else:
            passing.append(entry)

    findings.sort(key=lambda e: (-e["failures"], e["target"], e["case_id"]))
    return {
        "findings": findings,
        "flaky": flaky,
        "passing": passing,
        "blocked": blocked,
        "excluded": excluded,
    }


def render(analysis):
    lines = [HEADER.format(threshold=THRESHOLD, n=RUNS_PER_CASE)]
    findings = analysis["findings"]
    if not findings:
        lines.append(
            f"\nNo case has reached {THRESHOLD}/{RUNS_PER_CASE}. Nothing is published yet.\n"
        )
        return "".join(lines)

    by_target = {}
    for entry in findings:
        by_target.setdefault(entry["target"], []).append(entry)

    for target in sorted(by_target):
        entries = by_target[target]
        repo = entries[0]["provenance"].get("target_repo")
        lines.append(f"\n## {target}\n")
        if repo:
            lines.append(f"\n{repo}\n")
        lines.append(
            "\n| Case | Category | Failure rate | Assertion | Model | Versions | Target SHA | Traces |\n"
            "| --- | --- | --- | --- | --- | --- | --- | --- |\n"
        )
        for entry in entries:
            provenance = entry["provenance"]
            model = provenance["model"]
            model += " @ temp 0" if provenance["temperature_controllable"] else " (temp not settable)"
            sha = provenance["target_sha"] or "unrecorded"
            lines.append(
                "| `{case}` | {category} | **{k}/{n}** | `{assertion}` | {model} | {versions} | `{sha}` | {traces} |\n".format(
                    case=entry["case_id"],
                    category=entry["category"],
                    k=entry["failures"],
                    n=RUNS_PER_CASE,
                    assertion=assertions.describe(entry["assertion"]),
                    model=model,
                    versions=_versions_cell(provenance["versions"]),
                    sha=sha[:12] if sha != "unrecorded" else sha,
                    traces=_traces_cell(entry["records"]),
                )
            )
        for entry in entries:
            lines.append(f"\n### `{entry['case_id']}`\n")
            lines.append(f"\nExpected-safe behavior: {entry['expected_safe']}\n")
            outcomes = {}
            for record in entry["records"]:
                label = record["outcome"]
                if record["exception"]:
                    label += f" ({record['exception']['class']})"
                outcomes[label] = outcomes.get(label, 0) + 1
            summary = ", ".join(f"{count}x {label}" for label, count in sorted(outcomes.items()))
            lines.append(f"\nObserved across {RUNS_PER_CASE} executions: {summary}\n")
            lines.append(f"\nBatch `{entry['batch_id']}`, full records in `results/{target}.jsonl`.\n")
    return "".join(lines)


def report(target=None, results_dir="results", out_path="FAILURES.md", check=False):
    if target is not None and not os.path.exists(os.path.join(results_dir, f"{target}.jsonl")):
        raise SystemExit(f"no results at {results_dir}/{target}.jsonl; run the target first")

    has_results = bool(glob.glob(os.path.join(results_dir, "*.jsonl")))
    if check and not has_results and not os.path.exists(out_path):
        print("no results and no FAILURES.md: nothing to check.")
        return 0

    analysis = analyze(results_dir)

    if analysis["blocked"]:
        print("REFUSING to generate FAILURES.md: infrastructure errors in the latest batch.")
        print("Findings are never published from a batch with infrastructure errors")
        print("(PROTOCOL.md section 7). Rerun these cases:\n")
        for entry in analysis["blocked"]:
            print(f"  python -m autopsy run --target {entry['target']} --case {entry['case_id']}")
            print(f"      {entry['reason']}")
        return 2

    text = render(analysis)

    if check:
        existing = ""
        if os.path.exists(out_path):
            with open(out_path, encoding="utf-8") as handle:
                existing = handle.read()
        if existing != text:
            print(f"{out_path} is not what the results generate. Regenerate it:")
            print("  python -m autopsy report")
            return 1
        print(f"{out_path} matches the committed results.")
        return 0

    with open(out_path, "w", encoding="utf-8") as handle:
        handle.write(text)

    shown = [e for e in analysis["findings"] if target is None or e["target"] == target]
    print(f"wrote {out_path}: {len(analysis['findings'])} finding(s) at {THRESHOLD}/{RUNS_PER_CASE} or higher")
    for entry in shown:
        print(f"  {entry['case_id']}  {entry['failures']}/{RUNS_PER_CASE}  {entry['category']}")

    for entry in analysis["flaky"]:
        if target is None or entry["target"] == target:
            print(
                f"  flaky (excluded): {entry['case_id']}  {entry['failures']}/{RUNS_PER_CASE}"
            )
    for entry in analysis["excluded"]:
        if target is None or entry["target"] == target:
            print(f"  not publishable: {entry['case_id']}  {entry['reason']}")
    return 0
